import pandas as pd

def clean(df):
    df = df.copy()
    if 'sex' in df.columns:
        df['sex'] = df['sex'].astype(str).str.strip()
    if 'body_mass_g' in df.columns:
        df['body_mass_g'] = df['body_mass_g'].astype(str).str.replace(',', '', regex=False)
        df['body_mass_g'] = pd.to_numeric(df['body_mass_g'], errors='coerce')
    return df

def answer(df):
    df_clean = df.dropna(subset=['sex', 'body_mass_g'])
    result = df_clean.groupby('sex')['body_mass_g'].mean().to_dict()
    return result
